syntax:
```cpp
// Using subscript operator (inserts if key doesn't exist)
map<string, int> wordCounts;
wordCounts["hello"]++; // Increments count if "hello" exists; otherwise, adds "hello" with count 1

// Using find() (returns iterator to element or end() if not found)
std::map<string, int>::iterator it = wordCounts.find("world");
if (it != wordCounts.end()) {
  std::cout << "Count of 'world': " << it->second << std::endl;
} else {
  std::cout << "'world' not found" << std::endl;
}

//Using count() (returns number of elements with the key)
int count = wordCounts.count("hello");
if (count > 0) {
  std::cout << "'hello' is present" << std::endl; 
}
```

code_example:
#include <iostream>
#include <map>
#include <string>
int main() {
  std::map<std::string, int> wordCounts;
  wordCounts["hello"] = 5; // Direct assignment
  if (wordCounts.count("hello")) {
    std::cout << "Hello count: " << wordCounts["hello"] << std::endl;
  }
  auto it = wordCounts.find("world");
  if (it != wordCounts.end()) {
    std::cout << "World count: " << it->second << std::endl;
  } else {
    std::cout << "World not found" << std::endl;
  }
  return 0;
}
